nextflow_process {

    name "Test Process FAQCS"
    script "../main.nf"
    config "./nextflow.config"
    process "FAQCS"

    tag "modules"
    tag "modules_nfcore"
    tag "faqcs"

    test("sarscov2 single-end [fastq]") {

        when {
            params {
                module_args = ""
            }
            process {
                """
                input[0] = channel.of([
                    [ id: 'test', single_end:true ],
                    [ file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true) ]
                ])
                """
            }
        }

        then {
            assertAll (
                { assert process.success },
                { assert process.out.debug          == [] },
                { assert process.out.reads_fail     == [] },
                { assert process.out.reads_unpaired == [] },
                { assert snapshot(
                    file(process.out.statspdf[0][1]).name,
                    process.out.reads,
                    process.out.stats,
                    process.out.log,
                    process.out.findAll{ key, val -> key.startsWith('versions') }
                ).match() }
            )
        }
    }

    test("sarscov2 paired-end [fastq]") {

        when {
            params {
                module_args = ""
            }
            process {
                """
                input[0] = channel.of([
                    [id: 'test', single_end: false],
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                    ]
                ])
                """
            }
        }

        then {
            assertAll (
                { assert process.success },
                { assert process.out.debug      == [] },
                { assert process.out.reads_fail == [] },
                { assert snapshot(
                    file(process.out.statspdf[0][1]).name,
                    process.out.reads,
                    process.out.reads_unpaired,
                    process.out.stats,
                    process.out.log,
                    process.out.findAll{ key, val -> key.startsWith('versions') }
                ).match() }
            )
        }
    }

    test("sarscov2 paired-end [fastq] options") {

        when {
            params {
                module_args = "--discard --adapter -q 35 --debug"
            }
            process {
                """
                input[0] = channel.of([
                    [id: 'test', single_end: false],
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                    ]
                ])
                """
            }
        }

        then {
            assertAll (
                { assert process.success },
                { assert snapshot(
                    file(process.out.statspdf[0][1]).name,
                    file(process.out.log[0][1]).name,
                    process.out.reads,
                    process.out.reads_unpaired,
                    process.out.stats,
                    process.out.debug,
                    process.out.reads_fail,
                    process.out.findAll{ key, val -> key.startsWith('versions') }
                ).match() }
            )
        }
    }

    test("sarscov2 single-end [fastq] qc_only") {

        when {
            params {
                module_args = "--qc_only"
            }
            process {
                """
                input[0] = channel.of([
                    [ id: 'test', single_end:true ],
                    [ file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true) ]
                ])
                """
            }
        }

        then {
            assertAll (
                { assert process.success },
                { assert process.out.reads          == [] },
                { assert process.out.reads_unpaired == [] },
                { assert process.out.reads_fail     == [] },
                { assert process.out.debug          == [] },
                { assert snapshot(
                    file(process.out.statspdf[0][1]).name,
                    process.out.stats,
                    process.out.findAll{ key, val -> key.startsWith('versions') }
                ).match() }
            )
        }
    }

    test("stub") {

        options "-stub"

        when {
            params {
                module_args = ""
            }
            process {
                """
                input[0] = [ [ id: 'test', single_end:true ], [] ]
                """
            }
        }

        then {
            assertAll (
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

